--
-- Functions
----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.active_users_with_watches(p_days integer DEFAULT 30)
 RETURNS TABLE(user_id uuid)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
  select u.id
  from auth.users u
  where u.last_sign_in_at > now() - make_interval(days => p_days)
    and not exists (select 1 from internal_accounts ia where ia.user_id = u.id)
    and exists (
      select 1 from watches w
      where w.user_id = u.id
        and trim(coalesce(w.brand, '')) <> ''
        and trim(coalesce(w.name, ''))  <> ''
    );
$function$;
CREATE OR REPLACE FUNCTION public.admin_active_dau()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  n timestamptz := now();
  floor60 timestamptz := now() - interval '60 days';   -- widest lookback (prev-30d start)
  internal uuid[] := ARRAY(SELECT user_id FROM internal_accounts);
  result json;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  WITH acts AS (
    SELECT user_id AS uid, last_seen_at AS ts FROM user_presence WHERE last_seen_at >= floor60
    UNION ALL SELECT user_id, created_at FROM logs WHERE created_at >= floor60
    UNION ALL SELECT user_id, created_at FROM watches WHERE created_at >= floor60
    UNION ALL SELECT id, last_sign_in_at FROM auth.users WHERE last_sign_in_at >= floor60
    UNION ALL SELECT user_id, created_at FROM timegrapher_results WHERE created_at >= floor60
    UNION ALL SELECT (messages::jsonb->>'user_id')::uuid, created_at
      FROM timegrapher_tick_logs
      WHERE messages LIKE '{"type":"session_summary"%' AND created_at >= floor60
    UNION ALL SELECT user_id, created_at FROM likes WHERE created_at >= floor60
    UNION ALL SELECT user_id, created_at FROM comments WHERE created_at >= floor60
    UNION ALL SELECT follower_id, created_at FROM follows WHERE created_at >= floor60
    UNION ALL SELECT user_id, created_at FROM comment_likes WHERE created_at >= floor60
    UNION ALL SELECT user_id, created_at FROM valuation_events WHERE created_at >= floor60
    UNION ALL SELECT user_id, created_at FROM identify_attempts WHERE created_at >= floor60
  ),
  ext AS (  -- real external users only: has a profile row (matches
            -- admin_last_active's FROM profiles), not internal, non-null uid.
    SELECT uid, ts FROM acts
    WHERE uid IS NOT NULL AND uid <> ALL(internal)
      AND uid IN (SELECT id FROM profiles)
  )
  SELECT json_build_object(
    'active_24h',      (SELECT count(DISTINCT uid) FROM ext WHERE ts >= n - interval '24 hours'),
    'active_prev_24h', (SELECT count(DISTINCT uid) FROM ext WHERE ts >= n - interval '48 hours' AND ts < n - interval '24 hours'),
    'active_7d',       (SELECT count(DISTINCT uid) FROM ext WHERE ts >= n - interval '7 days'),
    'active_prev_7d',  (SELECT count(DISTINCT uid) FROM ext WHERE ts >= n - interval '14 days' AND ts < n - interval '7 days'),
    'active_30d',      (SELECT count(DISTINCT uid) FROM ext WHERE ts >= n - interval '30 days'),
    'active_prev_30d', (SELECT count(DISTINCT uid) FROM ext WHERE ts >= n - interval '60 days' AND ts < n - interval '30 days')
  ) INTO result;

  RETURN result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_active_days(target_user_id uuid, window_days integer DEFAULT 30)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT count(DISTINCT day)::bigint FROM (
    SELECT created_at::date AS day FROM logs WHERE user_id = target_user_id AND created_at >= NOW() - (window_days || ' days')::interval
    UNION ALL SELECT created_at::date FROM watches WHERE user_id = target_user_id AND created_at >= NOW() - (window_days || ' days')::interval
    UNION ALL SELECT created_at::date FROM timegrapher_results WHERE user_id = target_user_id AND created_at >= NOW() - (window_days || ' days')::interval
    UNION ALL SELECT created_at::date FROM valuation_events WHERE user_id = target_user_id AND created_at >= NOW() - (window_days || ' days')::interval
    UNION ALL SELECT created_at::date FROM identify_attempts WHERE user_id = target_user_id AND created_at >= NOW() - (window_days || ' days')::interval
  ) d;
$function$;
CREATE OR REPLACE FUNCTION public.admin_broadcast_batch_metrics(p_label text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare result json;
begin
  if not exists (select 1 from public.profiles p where p.id = auth.uid() and p.is_admin) then
    raise exception 'Not authorized';
  end if;

  with q as (
    select id, email, subject, sent_at
    from public.broadcast_queue
    where coalesce(label, subject) = p_label
      and status = 'sent'
      and sent_at is not null
  ), ev as (
    select
      q.id as qid,
      e.event_type,
      -- True event time: the old Resend webhook wrote the email's timestamp on
      -- every event row, so created_at cannot be used to measure open lag.
      coalesce((e.raw->'open'->>'timestamp')::timestamptz,
               (e.raw->'delivery'->>'timestamp')::timestamptz,
               (e.raw->'mail'->>'timestamp')::timestamptz,
               (e.raw->>'created_at')::timestamptz,
               e.created_at) as evt
    from q
    join public.email_events e
      on e.email_to = q.email
     -- Wide enough to cover a batch stamped after its own sends; see header.
     and e.created_at >= q.sent_at - interval '1 hour'
     and e.created_at <  q.sent_at + interval '48 hours'
     -- Campaign-scoped, except unsubscribes, which carry a category here.
     and (e.event_type = 'unsubscribed' or e.subject = q.subject)
  ), base as (
    select qid, min(evt) filter (where event_type = 'delivered') as t0
    from ev
    group by qid
  ), per_row as (
    select
      q.id,
      bool_or(ev.event_type = 'delivered')    as delivered,
      bool_or(ev.event_type = 'opened')       as opened,
      -- No delivery event to measure against => not provably a prefetch.
      bool_or(ev.event_type = 'opened'
              and (b.t0 is null or ev.evt - b.t0 >= interval '30 seconds')) as opened_human,
      bool_or(ev.event_type = 'unsubscribed') as unsubscribed,
      bool_or(ev.event_type = 'bounced')      as bounced,
      bool_or(ev.event_type = 'complained')   as complained
    from q
    left join ev on ev.qid = q.id
    left join base b on b.qid = q.id
    group by q.id
  )
  select json_build_object(
    'sent',         count(*),
    'delivered',    count(*) filter (where delivered),
    'opened',       count(*) filter (where opened),
    'opened_human', count(*) filter (where opened_human),
    'unsubscribed', count(*) filter (where unsubscribed),
    'bounced',      count(*) filter (where bounced),
    'complained',   count(*) filter (where complained)
  )
  into result
  from per_row;

  return coalesce(result, json_build_object(
    'sent', 0, 'delivered', 0, 'opened', 0, 'opened_human', 0,
    'unsubscribed', 0, 'bounced', 0, 'complained', 0));
end;
$function$;
CREATE OR REPLACE FUNCTION public.admin_broadcast_queue_status()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result json;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT json_build_object(
    'pending', (SELECT count(*) FROM broadcast_queue WHERE status = 'pending'),
    'held',    (SELECT count(*) FROM broadcast_queue WHERE status = 'held'),
    'sent',    (SELECT count(*) FROM broadcast_queue WHERE status = 'sent'),
    'failed',  (SELECT count(*) FROM broadcast_queue WHERE status = 'failed'),
    'used_today', (SELECT count(*) FROM email_events WHERE event_type = 'sent'
                    AND created_at >= date_trunc('day', now() AT TIME ZONE 'utc') AT TIME ZONE 'utc'),
    'sent_today', (SELECT count(*) FROM broadcast_queue WHERE status = 'sent'
                    AND sent_at >= date_trunc('day', now() AT TIME ZONE 'utc') AT TIME ZONE 'utc'),
    'breakdown', (
      SELECT coalesce(json_agg(b ORDER BY
                        (b.pending = 0 AND b.held = 0),
                        b.rank,
                        b.first_queued_at DESC
                      ), '[]'::json)
      FROM (
        SELECT coalesce(label, subject) AS label,
               count(*)                                  AS total,
               count(*) FILTER (WHERE status = 'pending') AS pending,
               count(*) FILTER (WHERE status = 'held')    AS held,
               count(*) FILTER (WHERE status = 'sent')    AS sent,
               count(*) FILTER (WHERE status = 'failed')  AS failed,
               count(*) FILTER (WHERE status = 'sent'
                 AND sent_at >= date_trunc('day', now() AT TIME ZONE 'utc') AT TIME ZONE 'utc')
                                                          AS sent_today,
               min(priority) FILTER (WHERE status = 'pending') AS rank,
               min(created_at)                            AS first_queued_at,
               max(sent_at)                               AS last_sent
        FROM broadcast_queue
        GROUP BY 1
      ) b
    )
  ) INTO result;
  RETURN result;
END; $function$;
CREATE OR REPLACE FUNCTION public.admin_cancel_broadcast(p_label text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare cancelled int;
begin
  if not exists (select 1 from public.profiles p where p.id = auth.uid() and p.is_admin) then
    raise exception 'Not authorized';
  end if;
  delete from public.broadcast_queue
   where status = 'held'
     and coalesce(label, subject) = p_label;
  get diagnostics cancelled = row_count;
  return json_build_object('cancelled', cancelled);
end;
$function$;
CREATE OR REPLACE FUNCTION public.admin_demo_views()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE result json;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT json_build_object(
    'total',      count(*),
    'unique_ips', count(DISTINCT ip_hash),
    'views_1d',   count(*) FILTER (WHERE created_at >= now() - interval '1 day'),
    'unique_1d',  count(DISTINCT ip_hash) FILTER (WHERE created_at >= now() - interval '1 day'),
    'views_7d',   count(*) FILTER (WHERE created_at >= now() - interval '7 days'),
    'unique_7d',  count(DISTINCT ip_hash) FILTER (WHERE created_at >= now() - interval '7 days')
  ) INTO result FROM demo_views;

  RETURN result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_dod_counts()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  d24h timestamptz := now() - interval '24 hours';
  internal_ids uuid[] := ARRAY(SELECT user_id FROM internal_accounts);
  result json;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT json_build_object(
    'users',        (SELECT count(*) FROM profiles WHERE created_at >= d24h AND id != ALL(internal_ids)),
    'watches',      (SELECT count(*) FROM watches  WHERE created_at >= d24h AND user_id != ALL(internal_ids)),
    'wears',        (SELECT count(*) FROM logs     WHERE watch_id IS NOT NULL AND created_at >= d24h AND user_id != ALL(internal_ids)),
    'priceChecks',  (SELECT count(*) FROM valuation_events  WHERE created_at >= d24h AND user_id != ALL(internal_ids)),
    'enhances',     (SELECT count(*) FROM identify_attempts WHERE mode = 'enhance' AND created_at >= d24h AND user_id != ALL(internal_ids)),
    'measurements', (SELECT count(*) FROM timegrapher_tick_logs
                      WHERE messages LIKE '{"type":"session_summary"%' AND created_at >= d24h
                        AND COALESCE((messages::jsonb->>'user_id')::uuid <> ALL(internal_ids), true)),
    'wish',         (SELECT count(*) FROM wishlist WHERE created_at >= d24h AND user_id != ALL(internal_ids)),
    'clubs',        (SELECT count(*) FROM clubs    WHERE created_at >= d24h AND created_by != ALL(internal_ids)),
    'follows',      (SELECT count(*) FROM follows  WHERE created_at >= d24h AND follower_id != ALL(internal_ids)),
    'friends',      (SELECT count(*) FROM friend_requests WHERE status = 'accepted' AND created_at >= d24h AND initiator_id != ALL(internal_ids)),
    'likes',        (SELECT count(*) FROM likes    WHERE created_at >= d24h AND user_id != ALL(internal_ids)),
    'comments',     (SELECT count(*) FROM comments WHERE created_at >= d24h AND user_id != ALL(internal_ids))
  ) INTO result;

  RETURN result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_email_clickthrough()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result json;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT coalesce(json_agg(row_to_json(c) ORDER BY c.visits DESC, c.campaign), '[]'::json)
  INTO result
  FROM (
    SELECT
      v.utm_campaign                                   AS campaign,
      coalesce(v.utm_medium, 'campaign')               AS medium,
      count(*)                                         AS visits,
      count(*) FILTER (WHERE v.created_at >= now() - interval '24 hours') AS visits_24h,
      -- Signed-in click-throughs. Anonymous ones still count as visits; they
      -- are people who tapped through without a session on that device.
      count(DISTINCT v.user_id) FILTER (WHERE v.user_id IS NOT NULL) AS known_users,
      max(v.created_at)                                AS last_visit
    FROM page_visits v
    WHERE v.utm_source = 'email'
      AND v.utm_campaign IS NOT NULL
      -- Only mediums we actually emit. Scanners fuzz the query string --
      -- utm_campaign=jfydbzf&utm_medium=dbzcbvta has hit twice -- and a
      -- card of real campaigns should not carry someone's fuzzer output.
      AND v.utm_medium IN ('campaign', 'broadcast')
      AND v.created_at >= now() - interval '90 days'
      -- Our own test suite writes here; see the header.
      AND (v.user_agent IS NULL OR v.user_agent !~* 'HeadlessChrome|Playwright|Puppeteer|Electron')
      AND (v.user_id IS NULL OR NOT EXISTS (
            SELECT 1 FROM internal_accounts i WHERE i.user_id = v.user_id))
    GROUP BY 1, 2
  ) c;

  RETURN result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_email_engagement()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  d24h timestamptz := now() - interval '24 hours';
  -- Below this lag from delivery, an open is a mail-client prefetch, not a read.
  prefetch_window interval := interval '30 seconds';
  result json;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  -- Internal email is excluded from every figure here, filtered by RECIPIENT.
  -- Two sources, because neither alone is enough:
  --   1. internal_accounts -> auth.users.email  (founder + official/demo/test
  --      logins). Single source of truth per CLAUDE.md; no UUIDs hardcoded.
  --   2. anything @wrotate.com. Company mailboxes like support@ are NOT user
  --      accounts, so (1) misses them -- and support@ alone receives 744 events,
  --      all "New WRotate user:" signup alerts, which forward to the founder.
  --      Verified: the only @wrotate.com auth users are official/test/test2/demo,
  --      all internal, so excluding the whole domain cannot drop a real user.
  -- Subject-pattern filtering was tried first and kept missing new variants
  -- ("WRotate Weekly Measurement Review", "weekly-review FAILED"); matching on
  -- recipient is what makes this hold as new internal mail is added.
  WITH internal AS (
    SELECT lower(u.email) AS email
    FROM internal_accounts ia
    JOIN auth.users u ON u.id = ia.user_id
    WHERE u.email IS NOT NULL
  ), ext AS (
    -- Bounded to 90 days and to the columns actually used. This aggregated the
    -- whole table with SELECT *; intake jumped 4.6x during the SES migration
    -- week, which put an unbounded seq-scan on a path to seconds per page load.
    SELECT e.event_type, e.email_id, e.email_to, e.subject, e.created_at,
           -- True event time; see the header note on Resend's created_at.
           coalesce((e.raw->'open'->>'timestamp')::timestamptz,
                    (e.raw->'delivery'->>'timestamp')::timestamptz,
                    (e.raw->'mail'->>'timestamp')::timestamptz,
                    (e.raw->>'created_at')::timestamptz,
                    e.created_at) AS evt_ts
    FROM email_events e
    WHERE e.created_at >= now() - interval '90 days'
      AND e.email_to IS NOT NULL
      AND lower(e.email_to) NOT IN (SELECT email FROM internal)
      AND lower(e.email_to) NOT LIKE '%@wrotate.com'
  ), msg AS (
    -- Delivery baseline per message. 'delivered' is the honest zero point; fall
    -- back to 'sent' for providers/paths that never emit a delivery event.
    SELECT email_id,
           coalesce(min(evt_ts) FILTER (WHERE event_type = 'delivered'),
                    min(evt_ts) FILTER (WHERE event_type = 'sent')) AS t0
    FROM ext
    GROUP BY email_id
  ), extm AS (
    -- `machine` is only meaningful on an 'opened' row. NULL t0 (baseline older
    -- than the 90-day window) => not provably a prefetch => counted as human.
    SELECT e.*,
           (e.event_type = 'opened'
            AND m.t0 IS NOT NULL
            AND e.evt_ts - m.t0 < prefetch_window) AS machine
    FROM ext e
    LEFT JOIN msg m USING (email_id)
  ), bq AS (
    -- One label per (recipient, subject). DISTINCT ON keeps the join from
    -- fanning out and multiplying an event if the same person were ever queued
    -- twice under the same rendered subject; newest queue row wins.
    SELECT DISTINCT ON (lower(email), subject)
      lower(email) AS em, subject, label
    FROM broadcast_queue
    WHERE label IS NOT NULL AND email IS NOT NULL AND subject IS NOT NULL
    ORDER BY lower(email), subject, created_at DESC
  ), ext_l AS (
    SELECT e.event_type, e.email_id, e.email_to, e.subject, e.created_at, e.machine, b.label
    FROM extm e
    LEFT JOIN bq b ON b.em = lower(e.email_to) AND b.subject = e.subject
  ), qlab AS (
    -- `held` is counted alongside `pending`: a staged send sits at pending = 0
    -- with its remainder held for review, and counting only pending dropped it
    -- out of "Broadcast - in progress" into "Older campaigns" while it was very
    -- much still in flight.
    SELECT label,
           count(*) FILTER (WHERE status = 'pending') AS pending,
           count(*) FILTER (WHERE status = 'held')    AS held
    FROM broadcast_queue
    WHERE label IS NOT NULL
    GROUP BY label
  ), blab AS (
    SELECT
      label,
      count(*) FILTER (WHERE event_type = 'sent') AS sent,
      count(*) FILTER (WHERE event_type = 'delivered') AS delivered,
      count(DISTINCT email_id) FILTER (WHERE event_type = 'opened') AS opened,
      count(DISTINCT email_id) FILTER (WHERE event_type = 'opened' AND NOT machine) AS opened_human,
      count(DISTINCT email_id) FILTER (WHERE event_type = 'clicked') AS clicked,
      count(*) FILTER (WHERE event_type IN ('bounced','complained')) AS bounced,
      count(*) FILTER (WHERE event_type = 'sent'      AND created_at >= d24h) AS sent_24h,
      count(*) FILTER (WHERE event_type = 'delivered' AND created_at >= d24h) AS delivered_24h,
      count(DISTINCT email_id) FILTER (WHERE event_type = 'opened'  AND created_at >= d24h) AS opened_24h,
      count(DISTINCT email_id) FILTER (WHERE event_type = 'opened'  AND NOT machine AND created_at >= d24h) AS opened_human_24h,
      count(DISTINCT email_id) FILTER (WHERE event_type = 'clicked' AND created_at >= d24h) AS clicked_24h,
      count(*) FILTER (WHERE event_type IN ('bounced','complained') AND created_at >= d24h) AS bounced_24h
    FROM ext_l
    WHERE label IS NOT NULL AND event_type <> 'unsubscribed'
    GROUP BY label
  )
  SELECT json_build_object(
    'by_subject', (
      SELECT coalesce(json_agg(row_to_json(s)), '[]'::json)
      FROM (
        SELECT
          subject,
          count(*) FILTER (WHERE event_type = 'sent') AS sent,
          count(*) FILTER (WHERE event_type = 'delivered') AS delivered,
          -- DISTINCT email_id: 'delivered' is one event per email but 'opened'
          -- fires per open (prefetch, re-opens), so raw counts rendered 200% and
          -- 300% open rates. Also makes this robust to duplicate webhook rows.
          count(DISTINCT email_id) FILTER (WHERE event_type = 'opened') AS opened,
          -- Opens with a real human behind them: at least one open >= 30s after
          -- delivery. See the header note.
          count(DISTINCT email_id) FILTER (WHERE event_type = 'opened' AND NOT machine) AS opened_human,
          count(DISTINCT email_id) FILTER (WHERE event_type = 'clicked') AS clicked,
          count(*) FILTER (WHERE event_type IN ('bounced','complained')) AS bounced,
          -- Last-24h counterparts. Same filters, same DISTINCT rule, one window.
          count(*) FILTER (WHERE event_type = 'sent'      AND created_at >= d24h) AS sent_24h,
          count(*) FILTER (WHERE event_type = 'delivered' AND created_at >= d24h) AS delivered_24h,
          count(DISTINCT email_id) FILTER (WHERE event_type = 'opened'  AND created_at >= d24h) AS opened_24h,
          count(DISTINCT email_id) FILTER (WHERE event_type = 'opened'  AND NOT machine AND created_at >= d24h) AS opened_human_24h,
          count(DISTINCT email_id) FILTER (WHERE event_type = 'clicked' AND created_at >= d24h) AS clicked_24h,
          count(*) FILTER (WHERE event_type IN ('bounced','complained') AND created_at >= d24h) AS bounced_24h
        FROM ext_l
        WHERE subject IS NOT NULL
          -- See note 1 above: `subject` holds the unsub category, not a campaign.
          AND event_type <> 'unsubscribed'
          -- Broadcast sends are reported under their label in 'broadcasts';
          -- leaving them here too would double-count them.
          AND label IS NULL
        GROUP BY subject
      ) s
    ),
    -- One row per broadcast campaign, keyed by the operator-chosen label.
    -- pending > 0 (draining) or held > 0 (staged, awaiting release) means
    -- the campaign is still in flight.
    'broadcasts', (
      SELECT coalesce(json_agg(row_to_json(b) ORDER BY (b.pending + b.held) DESC, b.delivered DESC), '[]'::json)
      FROM (
        SELECT
          q.label,
          q.pending,
          q.held,
          coalesce(e.sent, 0)      AS sent,
          coalesce(e.delivered, 0) AS delivered,
          coalesce(e.opened, 0)    AS opened,
          coalesce(e.opened_human, 0) AS opened_human,
          coalesce(e.clicked, 0)   AS clicked,
          coalesce(e.bounced, 0)   AS bounced,
          coalesce(e.sent_24h, 0)      AS sent_24h,
          coalesce(e.delivered_24h, 0) AS delivered_24h,
          coalesce(e.opened_24h, 0)    AS opened_24h,
          coalesce(e.opened_human_24h, 0) AS opened_human_24h,
          coalesce(e.clicked_24h, 0)   AS clicked_24h,
          coalesce(e.bounced_24h, 0)   AS bounced_24h
        FROM qlab q
        LEFT JOIN blab e ON e.label = q.label
      ) b
    ),
    'recent', (
      SELECT coalesce(json_agg(row_to_json(r)), '[]'::json)
      FROM (
        SELECT event_type, email_to, created_at, machine
        FROM extm
        WHERE event_type IN ('opened','clicked')
        ORDER BY created_at DESC
        LIMIT 40
      ) r
    ),
    -- Account-health counters. SES suspends above 5% bounce or 0.1% complaint,
    -- so these two must stay separate — a merged figure cannot be tested
    -- against either threshold.
    'health', (
      SELECT json_build_object(
        'sent_24h',       count(*) FILTER (WHERE event_type = 'sent'       AND created_at >= now() - interval '24 hours'),
        'bounced_24h',    count(*) FILTER (WHERE event_type = 'bounced'    AND created_at >= now() - interval '24 hours'),
        'complained_24h', count(*) FILTER (WHERE event_type = 'complained' AND created_at >= now() - interval '24 hours'),
        'sent_7d',        count(*) FILTER (WHERE event_type = 'sent'),
        'bounced_7d',     count(*) FILTER (WHERE event_type = 'bounced'),
        'complained_7d',  count(*) FILTER (WHERE event_type = 'complained')
      )
      FROM ext
      WHERE created_at >= now() - interval '7 days'
    )
  ) INTO result;

  RETURN result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_email_stats()
 RETURNS TABLE(event_type text, cnt bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
#variable_conflict use_column
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  RETURN QUERY
  SELECT e.event_type, count(*) AS cnt FROM email_events e GROUP BY e.event_type;
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_engine_stats()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result json;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  WITH s AS (
    SELECT substring(messages from '"user_id"\s*:\s*"([0-9a-f-]{36})"') AS uid,
           CASE WHEN substring(messages from '"algo"\s*:\s*"([a-z]+)"') = 'tg'
                THEN 'tg' ELSE 'original' END AS engine,
           created_at
    FROM timegrapher_tick_logs
    WHERE messages LIKE '{"type":"session_summary"%'
  ), ext AS (
    SELECT * FROM s
    WHERE uid IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM internal_accounts ia WHERE ia.user_id::text = s.uid)
  )
  SELECT json_build_object(
    'prov2_users',        (SELECT count(DISTINCT uid) FROM ext WHERE engine = 'tg'),
    'prov2_sessions',     (SELECT count(*)            FROM ext WHERE engine = 'tg'),
    'prov2_sessions_24h', (SELECT count(*) FROM ext WHERE engine = 'tg'
                            AND created_at >= now() - interval '24 hours'),
    'prov2_sessions_prev24h', (SELECT count(*) FROM ext WHERE engine = 'tg'
                            AND created_at >= now() - interval '48 hours'
                            AND created_at <  now() - interval '24 hours'),
    'orig_users',         (SELECT count(DISTINCT uid) FROM ext WHERE engine = 'original'),
    'orig_sessions',      (SELECT count(*)            FROM ext WHERE engine = 'original'),
    'orig_sessions_24h',  (SELECT count(*) FROM ext WHERE engine = 'original'
                            AND created_at >= now() - interval '24 hours'),
    'orig_sessions_prev24h', (SELECT count(*) FROM ext WHERE engine = 'original'
                            AND created_at >= now() - interval '48 hours'
                            AND created_at <  now() - interval '24 hours')
  ) INTO result;
  RETURN result;
END; $function$;
CREATE OR REPLACE FUNCTION public.admin_fact_counts()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  d24h timestamptz := now() - interval '24 hours';
  internal_ids uuid[] := array(select user_id from internal_accounts);
  result json;
begin
  if not exists (select 1 from profiles where id = auth.uid() and is_admin = true) then
    raise exception 'Not authorized';
  end if;

  select json_build_object(
    'clicks_total',      (select count(*) from fact_clicks where user_id <> all(internal_ids)),
    'clicks_24h',        (select count(*) from fact_clicks where created_at >= d24h and user_id <> all(internal_ids)),
    'viewers_total',     (select count(distinct user_id) from fact_clicks where user_id <> all(internal_ids)),
    'viewers_24h',       (select count(distinct user_id) from fact_clicks where created_at >= d24h and user_id <> all(internal_ids)),
    'impressions_total', (select count(*) from fact_impressions where user_id <> all(internal_ids)),
    'impressions_24h',   (select count(*) from fact_impressions where created_at >= d24h and user_id <> all(internal_ids)),
    'generated_total',   (select count(*) from watch_facts),
    'generated_24h',     (select count(*) from watch_facts where created_at >= d24h),
    'watches_total',     (select count(distinct model_key) from watch_facts),
    'watches_24h',       (select count(distinct wf.model_key) from watch_facts wf
                           where not exists (
                             select 1 from watch_facts wf2
                             where wf2.model_key = wf.model_key and wf2.created_at < d24h))
  ) into result;

  return result;
end;
$function$;
CREATE OR REPLACE FUNCTION public.admin_feature_post(p_log_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM logs WHERE id = p_log_id
      AND visibility = 'public'
      AND (moderation_status IS NULL OR moderation_status <> 'removed')
  ) THEN
    RAISE EXCEPTION 'Post is not eligible to be featured (must be a public, non-removed post)';
  END IF;
  IF EXISTS (SELECT 1 FROM featured_posts WHERE log_id = p_log_id AND status IN ('queued','active')) THEN
    RAISE EXCEPTION 'Post is already featured or queued';
  END IF;
  INSERT INTO featured_posts(log_id, enqueued_by) VALUES (p_log_id, auth.uid());
  PERFORM featured_rotate();
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_featured_queue()
 RETURNS TABLE(id uuid, log_id text, status text, activated_at timestamp with time zone, expires_at timestamp with time zone, enqueued_at timestamp with time zone, notes text, photo_url text, user_id uuid, display_name text, username text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- profiles.id qualified: 'id' is also a RETURNS TABLE out-param here, so an
  -- unqualified reference is ambiguous (PL/pgSQL variable vs. table column).
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  PERFORM featured_rotate();
  RETURN QUERY
  SELECT fp.id, fp.log_id, fp.status, fp.activated_at, fp.expires_at, fp.enqueued_at,
         l.notes, l.photo_url, l.user_id, pr.display_name, pr.username
  FROM featured_posts fp
  JOIN logs l ON l.id = fp.log_id
  LEFT JOIN profiles pr ON pr.id = l.user_id
  WHERE fp.status IN ('queued','active')
  ORDER BY (fp.status = 'active') DESC, fp.enqueued_at ASC;
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_last_active()
 RETURNS TABLE(user_id uuid, last_active timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  RETURN QUERY
  SELECT p.id,
    GREATEST(pr.last_seen_at, l.mc, w.mc, au.last_sign_in_at, tr.mc, tg.mc,
             lk.mc, cm.mc, fl.mc, cl.mc, ve.mc, ia.mc)
  FROM profiles p
  LEFT JOIN user_presence pr ON pr.user_id = p.id
  LEFT JOIN (SELECT logs.user_id AS uid, max(logs.created_at) AS mc FROM logs GROUP BY logs.user_id) l ON l.uid = p.id
  LEFT JOIN (SELECT watches.user_id AS uid, max(watches.created_at) AS mc FROM watches GROUP BY watches.user_id) w ON w.uid = p.id
  LEFT JOIN auth.users au ON au.id = p.id
  LEFT JOIN (SELECT timegrapher_results.user_id AS uid, max(timegrapher_results.created_at) AS mc FROM timegrapher_results GROUP BY timegrapher_results.user_id) tr ON tr.uid = p.id
  LEFT JOIN (
    SELECT (messages::jsonb->>'user_id')::uuid AS uid, max(created_at) AS mc
    FROM timegrapher_tick_logs
    WHERE messages LIKE '{"type":"session_summary"%'
    GROUP BY 1
  ) tg ON tg.uid = p.id
  LEFT JOIN (SELECT likes.user_id AS uid, max(likes.created_at) AS mc FROM likes GROUP BY likes.user_id) lk ON lk.uid = p.id
  LEFT JOIN (SELECT comments.user_id AS uid, max(comments.created_at) AS mc FROM comments GROUP BY comments.user_id) cm ON cm.uid = p.id
  LEFT JOIN (SELECT follows.follower_id AS uid, max(follows.created_at) AS mc FROM follows GROUP BY follows.follower_id) fl ON fl.uid = p.id
  LEFT JOIN (SELECT comment_likes.user_id AS uid, max(comment_likes.created_at) AS mc FROM comment_likes GROUP BY comment_likes.user_id) cl ON cl.uid = p.id
  LEFT JOIN (SELECT valuation_events.user_id AS uid, max(valuation_events.created_at) AS mc FROM valuation_events GROUP BY valuation_events.user_id) ve ON ve.uid = p.id
  LEFT JOIN (SELECT identify_attempts.user_id AS uid, max(identify_attempts.created_at) AS mc FROM identify_attempts GROUP BY identify_attempts.user_id) ia ON ia.uid = p.id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_measurement_counts()
 RETURNS TABLE(user_id uuid, count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
#variable_conflict use_column
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  RETURN QUERY
  SELECT
    COALESCE(s.user_id, r.user_id) AS user_id,
    GREATEST(COALESCE(r.saved, 0), COALESCE(s.sessions, 0)) AS count
  FROM (
    SELECT (t.messages::jsonb->>'user_id')::uuid AS user_id, count(*) AS sessions
    FROM timegrapher_tick_logs t
    WHERE t.messages LIKE '{"type":"session_summary"%'
    GROUP BY 1
  ) s
  FULL OUTER JOIN (
    SELECT tr.user_id, count(*) AS saved
    FROM timegrapher_results tr
    GROUP BY 1
  ) r ON s.user_id = r.user_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_move_broadcast(p_label text, p_direction integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_cur   integer;
  v_swap  text;
  v_n     integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_direction NOT IN (-1, 1) THEN
    RAISE EXCEPTION 'direction must be -1 or 1';
  END IF;

  -- Normalize: rank the still-pending broadcasts by their current effective
  -- order and write that rank back to every row of each label.
  WITH ranked AS (
    SELECT coalesce(label, subject) AS lbl,
           row_number() OVER (ORDER BY min(priority), min(id)) - 1 AS rnk
    FROM broadcast_queue
    WHERE status = 'pending'
    GROUP BY 1
  )
  UPDATE broadcast_queue q
     SET priority = r.rnk
    FROM ranked r
   WHERE coalesce(q.label, q.subject) = r.lbl
     AND q.status = 'pending'
     AND q.priority IS DISTINCT FROM r.rnk;

  SELECT min(priority) INTO v_cur
    FROM broadcast_queue
   WHERE status = 'pending' AND coalesce(label, subject) = p_label;
  IF v_cur IS NULL THEN
    RETURN json_build_object('moved', false, 'reason', 'no pending rows for that broadcast');
  END IF;

  SELECT count(DISTINCT coalesce(label, subject)) INTO v_n
    FROM broadcast_queue WHERE status = 'pending';
  IF (p_direction = -1 AND v_cur = 0) OR (p_direction = 1 AND v_cur >= v_n - 1) THEN
    RETURN json_build_object('moved', false, 'reason', 'already at the end of the queue');
  END IF;

  SELECT coalesce(label, subject) INTO v_swap
    FROM broadcast_queue
   WHERE status = 'pending' AND priority = v_cur + p_direction
   LIMIT 1;
  IF v_swap IS NULL THEN
    RETURN json_build_object('moved', false, 'reason', 'nothing to swap with');
  END IF;

  -- Swap the two ranks. Guarded to pending rows so already-sent history is
  -- never rewritten.
  UPDATE broadcast_queue
     SET priority = CASE WHEN coalesce(label, subject) = p_label
                         THEN v_cur + p_direction ELSE v_cur END
   WHERE status = 'pending'
     AND coalesce(label, subject) IN (p_label, v_swap);

  RETURN json_build_object('moved', true, 'label', p_label,
                           'from', v_cur, 'to', v_cur + p_direction, 'swapped_with', v_swap);
END; $function$;
CREATE OR REPLACE FUNCTION public.admin_push_stats()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result json;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  WITH ext AS (
    SELECT d.user_id, min(d.created_at) AS first_at
    FROM device_tokens d
    WHERE NOT EXISTS (SELECT 1 FROM internal_accounts ia WHERE ia.user_id = d.user_id)
    GROUP BY d.user_id
  )
  SELECT json_build_object(
    'push_users',        (SELECT count(*) FROM ext),
    'push_users_24h',    (SELECT count(*) FROM ext WHERE first_at >= now() - interval '24 hours'),
    'push_users_prev24h',(SELECT count(*) FROM ext WHERE first_at >= now() - interval '48 hours'
                                                    AND first_at <  now() - interval '24 hours'),
    'push_devices',      (SELECT count(*) FROM device_tokens d
                           WHERE NOT EXISTS (SELECT 1 FROM internal_accounts ia WHERE ia.user_id = d.user_id))
  ) INTO result;
  RETURN result;
END; $function$;
CREATE OR REPLACE FUNCTION public.admin_release_broadcast(p_label text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare released int;
begin
  if not exists (select 1 from public.profiles p where p.id = auth.uid() and p.is_admin) then
    raise exception 'Not authorized';
  end if;
  -- coalesce(label, subject) mirrors how admin_broadcast_queue_status groups,
  -- so the label the admin sees in the list is the one that matches here.
  update public.broadcast_queue
     set status = 'pending'
   where status = 'held'
     and coalesce(label, subject) = p_label;
  get diagnostics released = row_count;
  return json_build_object('released', released);
end;
$function$;
CREATE OR REPLACE FUNCTION public.admin_totals()
 RETURNS TABLE(follows_count bigint, likes_count bigint, valuation_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
#variable_conflict use_column
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  RETURN QUERY
  SELECT
    (SELECT count(*) FROM follows),
    (SELECT count(*) FROM likes),
    (SELECT count(*) FROM valuation_events);
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_traffic_stats()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  result json;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  WITH internal AS (
    SELECT user_id FROM internal_accounts
  ),
  filtered AS (
    SELECT
      created_at,
      utm_source,
      referrer,
      user_agent,
      user_id,
      CASE
        WHEN utm_source IN ('reddit', 'reddit_lp') OR utm_source LIKE 'reddit\_lp\_%' OR referrer ILIKE '%reddit.com%' THEN 'Reddit'
        WHEN referrer ILIKE '%google.com%' AND COALESCE(utm_source, '') != 'appstore_click' THEN 'Google'
        WHEN referrer ILIKE '%bing.com%' THEN 'Bing'
        WHEN referrer ILIKE '%duckduckgo%' THEN 'DuckDuckGo'
        WHEN referrer ILIKE '%t.co%' THEN 'Twitter / X'
        WHEN utm_source = 'appstore_click' THEN 'App Store link'
        WHEN utm_source = 'direct' OR (COALESCE(utm_source, '') = '' AND COALESCE(referrer, '') = '') THEN 'Direct'
        WHEN referrer IS NOT NULL AND referrer != '' THEN COALESCE(substring(referrer from '://([^/]+)'), referrer)
        ELSE COALESCE(NULLIF(utm_source, ''), 'Other')
      END AS source_name,
      CASE
        WHEN user_agent ~* 'Mobile|iPhone|iPod|Android.*Mobile|webOS|BlackBerry|Opera Mini|IEMobile' THEN 'mobile'
        WHEN user_agent ~* 'iPad|Android|Tablet' THEN 'tablet'
        WHEN user_agent IS NULL OR user_agent = '' THEN 'unknown'
        ELSE 'desktop'
      END AS device_type
    FROM page_visits
    WHERE (user_id IS NULL OR user_id NOT IN (SELECT user_id FROM internal))
      AND (user_agent IS NULL OR user_agent !~* 'HeadlessChrome|Playwright|Puppeteer|Electron')
      AND (utm_medium IS NULL OR utm_medium != 'funnel')
      AND NOT (
        COALESCE(utm_source, '') = ''
        AND referrer IS NOT NULL
        AND (referrer ILIKE '%accounts.google.com%' OR referrer ILIKE '%appleid.apple.com%')
      )
      AND NOT (utm_source ~ '^(signin_google|signin_apple|onboarding_step_\d+)$')
  )
  SELECT json_build_object(
    'by_source', (
      SELECT coalesce(json_agg(row_to_json(s) ORDER BY s.total DESC), '[]'::json)
      FROM (
        SELECT source_name AS source, count(*) AS total,
          count(*) FILTER (WHERE created_at >= NOW() - INTERVAL '1 day') AS day,
          count(*) FILTER (WHERE created_at >= NOW() - INTERVAL '7 days') AS week
        FROM filtered GROUP BY source_name
      ) s
    ),
    'by_device_7d', (
      SELECT coalesce(json_agg(row_to_json(d) ORDER BY d.count DESC), '[]'::json)
      FROM (
        SELECT device_type AS device, count(*) AS count
        FROM filtered WHERE created_at >= NOW() - INTERVAL '7 days'
        GROUP BY device_type
      ) d
    ),
    'daily', (
      SELECT coalesce(json_agg(row_to_json(dd) ORDER BY dd.day DESC), '[]'::json)
      FROM (
        SELECT created_at::date AS day, count(*) AS count
        FROM filtered WHERE created_at >= NOW() - INTERVAL '30 days'
        GROUP BY created_at::date ORDER BY day DESC LIMIT 14
      ) dd
    ),
    'funnel', (
      SELECT json_build_object(
        'signin_google_all', count(*) FILTER (WHERE utm_source = 'signin_google'),
        'signin_apple_all', count(*) FILTER (WHERE utm_source = 'signin_apple'),
        'signin_google_7d', count(*) FILTER (WHERE utm_source = 'signin_google' AND created_at >= NOW() - INTERVAL '7 days'),
        'signin_apple_7d', count(*) FILTER (WHERE utm_source = 'signin_apple' AND created_at >= NOW() - INTERVAL '7 days'),
        'signin_google_1d', count(*) FILTER (WHERE utm_source = 'signin_google' AND created_at >= NOW() - INTERVAL '1 day'),
        'signin_apple_1d', count(*) FILTER (WHERE utm_source = 'signin_apple' AND created_at >= NOW() - INTERVAL '1 day')
      )
      FROM page_visits
      WHERE utm_medium = 'funnel'
        AND utm_source IN ('signin_google', 'signin_apple')
        AND (user_id IS NULL OR user_id NOT IN (SELECT user_id FROM internal))
    ),
    'signups', json_build_object(
      'total', (SELECT count(*) FROM profiles WHERE id NOT IN (SELECT user_id FROM internal)),
      'last_1d', (SELECT count(*) FROM profiles WHERE id NOT IN (SELECT user_id FROM internal) AND created_at >= NOW() - INTERVAL '1 day'),
      'last_7d', (SELECT count(*) FROM profiles WHERE id NOT IN (SELECT user_id FROM internal) AND created_at >= NOW() - INTERVAL '7 days')
    ),
    'signups_by_source', (
      SELECT coalesce(json_agg(row_to_json(ss) ORDER BY ss.count DESC), '[]'::json)
      FROM (
        SELECT
          CASE
            WHEN pv.utm_source IN ('reddit', 'reddit_lp') OR pv.utm_source LIKE 'reddit\_lp\_%' OR pv.referrer ILIKE '%reddit.com%' THEN 'Reddit'
            WHEN pv.referrer ILIKE '%google.com%' THEN 'Google'
            WHEN pv.referrer ILIKE '%t.co%' THEN 'Twitter / X'
            WHEN pv.utm_source = 'direct' OR (COALESCE(pv.utm_source, '') = '' AND COALESCE(pv.referrer, '') = '') THEN 'Direct'
            WHEN pv.referrer IS NOT NULL AND pv.referrer != '' THEN COALESCE(substring(pv.referrer from '://([^/]+)'), pv.referrer)
            WHEN pv.utm_source IS NOT NULL THEN pv.utm_source
            ELSE 'Unknown'
          END AS source,
          count(*) AS count,
          count(*) FILTER (WHERE p.created_at >= NOW() - INTERVAL '1 day') AS day,
          count(*) FILTER (WHERE p.created_at >= NOW() - INTERVAL '7 days') AS week
        FROM profiles p
        LEFT JOIN LATERAL (
          SELECT utm_source, referrer
          FROM page_visits
          WHERE page_visits.user_id = p.id
          ORDER BY created_at ASC
          LIMIT 1
        ) pv ON true
        WHERE p.id NOT IN (SELECT user_id FROM internal)
        GROUP BY source
      ) ss
    )
  ) INTO result;

  RETURN result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_unfeature(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  DELETE FROM featured_posts WHERE id = p_id;
  PERFORM featured_rotate();
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_unfeature_log(p_log_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  DELETE FROM featured_posts WHERE log_id = p_log_id AND status IN ('queued','active');
  PERFORM featured_rotate();
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_unsub_stats()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result json;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  SELECT json_build_object(
    'unsub_total', (SELECT count(*) FROM profiles WHERE (email_prefs->>'updates') = 'false'),
    'unsub_24h', (SELECT count(*) FROM email_events WHERE event_type = 'unsubscribed'
                   AND created_at >= now() - interval '24 hours'),
    'unsub_prev24h', (SELECT count(*) FROM email_events WHERE event_type = 'unsubscribed'
                   AND created_at >= now() - interval '48 hours'
                   AND created_at <  now() - interval '24 hours')
  ) INTO result;
  RETURN result;
END; $function$;
CREATE OR REPLACE FUNCTION public.admin_user_detail(target_user_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  result json;
  v_last_active timestamptz;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT greatest(
    (SELECT last_seen_at FROM user_presence WHERE user_id = target_user_id),
    (SELECT max(created_at) FROM logs WHERE user_id = target_user_id),
    (SELECT max(created_at) FROM watches WHERE user_id = target_user_id),
    (SELECT last_sign_in_at FROM auth.users WHERE id = target_user_id),
    (SELECT max(created_at) FROM timegrapher_results WHERE user_id = target_user_id),
    (SELECT max(created_at) FROM timegrapher_tick_logs
       WHERE messages LIKE '{"type":"session_summary"%'
         AND (messages::jsonb->>'user_id')::uuid = target_user_id),
    (SELECT max(created_at) FROM likes WHERE user_id = target_user_id),
    (SELECT max(created_at) FROM comments WHERE user_id = target_user_id),
    (SELECT max(created_at) FROM follows WHERE follower_id = target_user_id),
    (SELECT max(created_at) FROM comment_likes WHERE user_id = target_user_id),
    (SELECT max(created_at) FROM valuation_events WHERE user_id = target_user_id),
    (SELECT max(created_at) FROM identify_attempts WHERE user_id = target_user_id)
  ) INTO v_last_active;

  SELECT json_build_object(
    'profile', (
      SELECT json_build_object(
        'id', p.id,
        'username', p.username,
        'display_name', p.display_name,
        'avatar_url', p.avatar_url,
        'bio', p.bio,
        'created_at', p.created_at,
        'profile_privacy', p.profile_privacy,
        'collection_visibility', p.collection_visibility,
        'is_suspended', p.is_suspended
      ) FROM profiles p WHERE p.id = target_user_id
    ),
    'last_active', v_last_active,
    'last_sign_in', v_last_active,
    'watches', (SELECT count(*) FROM watches WHERE user_id = target_user_id),
    'wears', (SELECT count(*) FROM logs WHERE user_id = target_user_id AND watch_id IS NOT NULL),
    'posts', (SELECT count(*) FROM logs WHERE user_id = target_user_id AND watch_id IS NULL),
    'wishlist', (SELECT count(*) FROM wishlist WHERE user_id = target_user_id),
    -- Measurement counts from tick_logs session_summary rows (timegrapher_results
    -- is RLS-blocked to the test user; the client used to compute these itself).
    'measurements_total', (
      SELECT count(*) FROM timegrapher_tick_logs
      WHERE messages LIKE '{"type":"session_summary"%'
        AND (messages::jsonb->>'user_id')::uuid = target_user_id
    ),
    'measurements_success', (
      SELECT count(*) FROM timegrapher_tick_logs
      WHERE messages LIKE '{"type":"session_summary"%'
        AND (messages::jsonb->>'user_id')::uuid = target_user_id
        AND ((messages::jsonb->>'converged')::boolean
             OR messages::jsonb->>'stop_reason' = 'converged')
    ),
    'advanced_sessions', (
      SELECT count(*) FROM timegrapher_tick_logs
      WHERE messages LIKE '{"type":"session_summary"%'
        AND (messages::jsonb->>'user_id')::uuid = target_user_id
        AND (messages::jsonb->>'advanced_used')::boolean
    ),
    'advanced_last_preset', (
      SELECT coalesce(messages::jsonb->>'adv_preset', 'custom')
      FROM timegrapher_tick_logs
      WHERE messages LIKE '{"type":"session_summary"%'
        AND (messages::jsonb->>'user_id')::uuid = target_user_id
        AND (messages::jsonb->>'advanced_used')::boolean
      ORDER BY created_at DESC LIMIT 1
    ),
    'enhances', (SELECT count(*) FROM identify_attempts WHERE user_id = target_user_id AND mode = 'enhance'),
    'price_checks', (SELECT count(*) FROM valuation_events WHERE user_id = target_user_id),
    'followers', (SELECT count(*) FROM follows WHERE following_id = target_user_id),
    'following', (SELECT count(*) FROM follows WHERE follower_id = target_user_id),
    'friends', (SELECT count(*) FROM friend_requests WHERE status = 'accepted' AND (initiator_id = target_user_id OR target_id = target_user_id)),
    'comments', (SELECT count(*) FROM comments WHERE user_id = target_user_id),
    'likes_given', (SELECT count(*) FROM likes WHERE user_id = target_user_id),
    'clubs', (SELECT count(*) FROM club_members WHERE user_id = target_user_id),
    'feedback_asked', (SELECT count(*) FROM review_prompt_events WHERE user_id = target_user_id),
    'feedback_given', (
      SELECT count(*) FROM (
        SELECT id FROM feedback WHERE user_id = target_user_id
        UNION ALL
        SELECT id FROM app_feedback WHERE user_id = target_user_id
      ) sub
    ),
    'active_days', (
      SELECT count(DISTINCT date_trunc('day', created_at))
      FROM logs WHERE user_id = target_user_id
    ),
    'first_activity', (
      SELECT least(
        (SELECT min(created_at) FROM logs WHERE user_id = target_user_id),
        (SELECT min(created_at) FROM watches WHERE user_id = target_user_id)
      )
    ),
    'last_activity', (
      SELECT greatest(
        (SELECT max(created_at) FROM logs WHERE user_id = target_user_id),
        (SELECT max(created_at) FROM watches WHERE user_id = target_user_id)
      )
    ),
    'watch_list', (
      SELECT coalesce(json_agg(json_build_object(
        'brand', brand, 'name', name, 'created_at', created_at
      ) ORDER BY created_at DESC), '[]'::json)
      FROM watches WHERE user_id = target_user_id
    )
  ) INTO result;

  RETURN result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_user_stats()
 RETURNS TABLE(user_id uuid, watches bigint, wears bigint, price_checks bigint, enhances bigint, recent_active_days bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  RETURN QUERY
  SELECT p.id AS user_id, COALESCE(w.cnt, 0) AS watches, COALESCE(l.cnt, 0) AS wears,
    COALESCE(v.cnt, 0) AS price_checks, COALESCE(e.cnt, 0) AS enhances,
    public.admin_active_days(p.id, 30) AS recent_active_days
  FROM profiles p
  LEFT JOIN (SELECT user_id, count(*) AS cnt FROM watches GROUP BY user_id) w ON w.user_id = p.id
  LEFT JOIN (SELECT user_id, count(*) AS cnt FROM logs WHERE watch_id IS NOT NULL AND use_case IS DISTINCT FROM 'measurement' GROUP BY user_id) l ON l.user_id = p.id
  LEFT JOIN (SELECT user_id, count(*) AS cnt FROM valuation_events GROUP BY user_id) v ON v.user_id = p.id
  LEFT JOIN (SELECT user_id, count(*) AS cnt FROM identify_attempts WHERE mode = 'enhance' GROUP BY user_id) e ON e.user_id = p.id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_valuation_counts()
 RETURNS TABLE(user_id uuid, count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
#variable_conflict use_column
BEGIN
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND is_admin = true) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  RETURN QUERY
  SELECT v.user_id, count(*) AS count FROM valuation_events v GROUP BY v.user_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_wishlist_share_stats()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  d24h timestamptz := now() - interval '24 hours';
  internal_ids uuid[] := array(select user_id from internal_accounts);
  result json;
begin
  if not exists (select 1 from profiles where id = auth.uid() and is_admin = true) then
    raise exception 'Not authorized';
  end if;

  select json_build_object(
    'links_total',   (select count(*) from wishlist_shares where user_id <> all(internal_ids)),
    'links_24h',     (select count(*) from wishlist_shares where created_at >= d24h and user_id <> all(internal_ids)),
    'sharers_total', (select count(distinct user_id) from wishlist_shares where user_id <> all(internal_ids)),
    'sharers_24h',   (select count(distinct user_id) from wishlist_shares where created_at >= d24h and user_id <> all(internal_ids)),
    'items_total',   (select coalesce(sum(cardinality(item_ids)), 0) from wishlist_shares where user_id <> all(internal_ids)),
    'opens_total',   (select coalesce(sum(views), 0) from wishlist_shares where user_id <> all(internal_ids)),
    'links_opened',  (select count(*) from wishlist_shares where views > 0 and user_id <> all(internal_ids)),
    'links_active',  (select count(*) from wishlist_shares where revoked_at is null and user_id <> all(internal_ids)),
    'links_revoked', (select count(*) from wishlist_shares where revoked_at is not null and user_id <> all(internal_ids))
  ) into result;

  return result;
end;
$function$;
