CREATE OR REPLACE FUNCTION public.bump_rate_limit(p_user uuid, p_fn text, p_window_floor timestamp with time zone, p_now timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  new_count integer;
BEGIN
  -- Atomic check-and-increment for rate_limits, replacing the edge functions'
  -- read-modify-write (which let concurrent same-user requests exceed the cap).
  -- Increment (keeping the existing window_start) while the stored window is still
  -- current (window_start >= p_window_floor); otherwise reset the window to p_now,
  -- count = 1. Single statement => atomic per (user_id, function_name) row.
  INSERT INTO rate_limits (user_id, function_name, window_start, request_count)
  VALUES (p_user, p_fn, p_now, 1)
  ON CONFLICT (user_id, function_name) DO UPDATE
    SET request_count = CASE WHEN rate_limits.window_start >= p_window_floor
                             THEN rate_limits.request_count + 1 ELSE 1 END,
        window_start  = CASE WHEN rate_limits.window_start >= p_window_floor
                             THEN rate_limits.window_start ELSE p_now END
  RETURNING request_count INTO new_count;
  RETURN new_count;
END;
$function$;
