CREATE OR REPLACE FUNCTION public.featured_current()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_log text;
BEGIN
  PERFORM featured_rotate();
  SELECT log_id INTO v_log FROM featured_posts WHERE status = 'active' LIMIT 1;
  RETURN v_log;
END;
$function$;
CREATE OR REPLACE FUNCTION public.featured_rotate()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_next uuid;
BEGIN
  -- Serialize concurrent rotations (every feed load calls this) so we never double-promote.
  PERFORM pg_advisory_xact_lock(hashtext('featured_rotate'));

  -- 1. Expire active rows past expiry or whose post is no longer eligible.
  UPDATE featured_posts fp SET status = 'expired'
  WHERE fp.status = 'active'
    AND (
      fp.expires_at <= now()
      OR NOT EXISTS (
        SELECT 1 FROM logs l
        WHERE l.id = fp.log_id
          AND l.visibility = 'public'
          AND (l.moderation_status IS NULL OR l.moderation_status <> 'removed')
      )
    );

  -- 2. Expire queued rows whose post is no longer eligible (hard-deleted handled by cascade).
  UPDATE featured_posts fp SET status = 'expired'
  WHERE fp.status = 'queued'
    AND NOT EXISTS (
      SELECT 1 FROM logs l
      WHERE l.id = fp.log_id
        AND l.visibility = 'public'
        AND (l.moderation_status IS NULL OR l.moderation_status <> 'removed')
    );

  -- 3. If nothing active, promote the oldest eligible queued row with a fresh 24h clock.
  IF NOT EXISTS (SELECT 1 FROM featured_posts WHERE status = 'active') THEN
    SELECT fp.id INTO v_next
    FROM featured_posts fp
    WHERE fp.status = 'queued'
    ORDER BY fp.enqueued_at ASC
    LIMIT 1;
    IF v_next IS NOT NULL THEN
      UPDATE featured_posts
      SET status = 'active', activated_at = now(), expires_at = now() + interval '24 hours'
      WHERE id = v_next;
    END IF;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fun_fact_vars(p_uids uuid[])
 RETURNS TABLE(user_id uuid, brand text, name text, model_key text, fact text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    u.id,
    w.brand,
    w.name,
    case when w.brand is null then null
         else lower(trim(w.brand)) || '|' || lower(trim(w.name)) end,
    f.fact
  from unnest(p_uids) as u(id)
  left join lateral (
    select w.brand, w.name
    from watches w
    where w.user_id = u.id
      and trim(coalesce(w.brand, '')) <> ''
      and trim(coalesce(w.name, ''))  <> ''
    order by w.created_at desc
    limit 1
  ) w on true
  left join lateral (
    select wf.fact
    from watch_facts wf
    where w.brand is not null
      and wf.model_key = lower(trim(w.brand)) || '|' || lower(trim(w.name))
      -- Same completeness bar as looksCompleteFact(): no rows cut mid-sentence
      -- by the early generation bug.
      and length(trim(wf.fact)) between 40 and 500
      and trim(wf.fact) ~ '[.!?]$'
    order by wf.position
    limit 1
  ) f on true;
$function$;
