CREATE OR REPLACE FUNCTION public.onboarding4_feature_state()
 RETURNS TABLE(user_id uuid, has_played boolean, strap_ct integer, o4_sent_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT w.user_id,
         bool_or(w.elo_rating IS NOT NULL AND w.elo_rating <> 1000) AS has_played,
         coalesce(sum(jsonb_array_length(coalesce(w.straps,'[]'::jsonb))),0)::int AS strap_ct,
         (SELECT max(s.sent_at) FROM email_campaign_sends s
           WHERE s.user_id = w.user_id
             AND s.campaign_id = (SELECT id FROM email_campaigns
                                   WHERE name = 'Onboarding 4 — Straps & Ranking Game')) AS o4_sent_at
  FROM watches w
  WHERE NOT EXISTS (SELECT 1 FROM internal_accounts ia WHERE ia.user_id = w.user_id)
  GROUP BY w.user_id;
$function$;
CREATE OR REPLACE FUNCTION public.one_and_done_winback_users(p_churn_days integer DEFAULT 14)
 RETURNS TABLE(user_id uuid)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select l.user_id
  from logs l
  where l.watch_id is not null
    and coalesce(l.use_case, '') <> 'measurement'
    and not exists (select 1 from internal_accounts i where i.user_id = l.user_id)
  group by l.user_id
  having count(*) = 1
     and max(l.created_at) < now() - make_interval(days => p_churn_days)
$function$;
CREATE OR REPLACE FUNCTION public.peek_watch_fact(p_brand text, p_name text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid   uuid := auth.uid();
  v_key   text := lower(trim(p_brand)) || '|' || lower(trim(p_name));
  v_last  int;
  v_pool  int;
  v_next  int;
  v_serve int;
  v_fact  public.watch_facts%rowtype;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;
  if coalesce(trim(p_brand), '') = '' or coalesce(trim(p_name), '') = '' then
    return json_build_object('fact_id', null, 'fact', null, 'needs_generation', true);
  end if;

  select last_position into v_last from public.watch_fact_progress
    where user_id = v_uid and model_key = v_key;
  if v_last is null then v_last := -1; end if;

  select count(*) into v_pool from public.watch_facts where model_key = v_key;
  v_next := v_last + 1;

  if v_pool = 0 then
    return json_build_object('fact_id', null, 'fact', null, 'needs_generation', true);
  end if;

  select min(f.position) into v_serve
    from public.watch_facts f
   where f.model_key = v_key
     and not exists (select 1 from public.logs l where l.fact_id = f.id)
     and not exists (select 1 from public.watch_fact_days d where d.fact_id = f.id);

  if v_serve is null then
    select min(f.position) into v_serve
      from public.watch_facts f
     where f.model_key = v_key
       and not exists (select 1 from public.logs l
                        where l.fact_id = f.id and l.user_id = v_uid)
       and not exists (select 1 from public.watch_fact_days d
                        where d.fact_id = f.id and d.user_id = v_uid);
  end if;

  -- Nothing this user has not already read. Write nothing; the caller skips.
  if v_serve is null then
    return json_build_object('fact_id', null, 'fact', null, 'needs_generation', true);
  end if;

  select * into v_fact from public.watch_facts
    where model_key = v_key and position = v_serve;
  if v_fact.id is null then
    return json_build_object('fact_id', null, 'fact', null, 'needs_generation', true);
  end if;

  -- last_wear_date stays NULL on purpose: the next wear log must advance again.
  insert into public.watch_fact_progress(user_id, model_key, last_position, last_wear_date, current_fact_id)
    values (v_uid, v_key, v_next, null, v_fact.id)
  on conflict (user_id, model_key) do update
    set last_position   = v_next,
        last_wear_date  = null,
        current_fact_id = v_fact.id,
        updated_at      = now();

  return json_build_object('fact_id', v_fact.id, 'fact', v_fact.fact, 'needs_generation', false);
end $function$;
CREATE OR REPLACE FUNCTION public.pick_watch_fact(p_brand text, p_name text, p_wear_date date, p_log_id text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid   uuid := auth.uid();
  v_key   text := lower(trim(p_brand)) || '|' || lower(trim(p_name));
  v_last  int;
  v_pool  int;
  v_next  int;
  v_serve int;
  v_fact  public.watch_facts%rowtype;
  v_dayid uuid;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  -- This wear_date already has a fact: return it, no advance, no generation.
  select fact_id into v_dayid from public.watch_fact_days
    where user_id = v_uid and model_key = v_key and wear_date = p_wear_date;
  if v_dayid is not null then
    select * into v_fact from public.watch_facts where id = v_dayid;
    if p_log_id is not null then
      update public.logs set fact_id = v_fact.id
        where id = p_log_id and user_id = v_uid and fact_id is null;
    end if;
    return json_build_object('fact_id', v_fact.id, 'fact', v_fact.fact,
                             'needs_generation', false, 'existing_facts', '[]'::json);
  end if;

  select last_position into v_last from public.watch_fact_progress
    where user_id = v_uid and model_key = v_key;
  if v_last is null then v_last := -1; end if;

  select count(*) into v_pool from public.watch_facts where model_key = v_key;
  v_next := v_last + 1;

  -- Lowest pool fact that has never been served to ANYONE. watch_fact_days is
  -- checked alongside logs because peek_watch_fact claims a fact for the login
  -- modal before any post exists to carry it.
  select min(f.position) into v_serve
    from public.watch_facts f
   where f.model_key = v_key
     and not exists (select 1 from public.logs l where l.fact_id = f.id)
     and not exists (select 1 from public.watch_fact_days d where d.fact_id = f.id);

  -- Nothing fresh in the pool. Below the cap, generate rather than repeat —
  -- this is what stops a second owner of the same watch reading the first
  -- owner's fact. existing_facts steers the generator off what is already there.
  if v_serve is null and v_pool < 10 then
    return json_build_object(
      'fact_id', null, 'fact', null, 'needs_generation', true,
      'existing_facts', coalesce(
        (select json_agg(f.fact order by f.position) from public.watch_facts f where f.model_key = v_key),
        '[]'::json));
  end if;

  -- At the cap: every fact is spoken for, so a repeat is unavoidable. Prefer one
  -- THIS user has not read before; fall back to the old cursor wrap.
  if v_serve is null then
    select min(f.position) into v_serve
      from public.watch_facts f
     where f.model_key = v_key
       and not exists (select 1 from public.logs l
                        where l.fact_id = f.id and l.user_id = v_uid)
       and not exists (select 1 from public.watch_fact_days d
                        where d.fact_id = f.id and d.user_id = v_uid);
  end if;
  if v_serve is null then
    v_serve := case when v_pool > 0 then v_next % v_pool else 0 end;
  end if;

  select * into v_fact from public.watch_facts where model_key = v_key and position = v_serve;
  if v_fact.id is null then
    return json_build_object('fact_id', null, 'fact', null, 'needs_generation', true,
                             'existing_facts', '[]'::json);
  end if;

  insert into public.watch_fact_progress(user_id, model_key, last_position, last_wear_date, current_fact_id)
    values (v_uid, v_key, v_next, p_wear_date, v_fact.id)
  on conflict (user_id, model_key) do update
    set last_position = excluded.last_position,
        last_wear_date = excluded.last_wear_date,
        current_fact_id = excluded.current_fact_id,
        updated_at = now();

  insert into public.watch_fact_days(user_id, model_key, wear_date, fact_id)
    values (v_uid, v_key, p_wear_date, v_fact.id)
  on conflict (user_id, model_key, wear_date) do nothing;

  if p_log_id is not null then
    update public.logs set fact_id = v_fact.id
      where id = p_log_id and user_id = v_uid and fact_id is null;
  end if;

  return json_build_object('fact_id', v_fact.id, 'fact', v_fact.fact,
                           'needs_generation', false, 'existing_facts', '[]'::json);
end $function$;
CREATE OR REPLACE FUNCTION public.promo_slot_stats()
 RETURNS TABLE(slot_id uuid, impressions bigint, clicks bigint, dismissals bigint, submissions bigint, thumbs_up bigint, thumbs_down bigint, distinct_users bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if not exists (select 1 from public.profiles p where p.id = auth.uid() and p.is_admin) then
    raise exception 'admin only';
  end if;
  return query
    select e.slot_id,
           count(*) filter (where e.event = 'impression'),
           count(*) filter (where e.event = 'click'),
           count(*) filter (where e.event = 'dismiss'),
           count(*) filter (where e.event = 'submit'),
           count(*) filter (where e.event = 'thumbs_up'),
           count(*) filter (where e.event = 'thumbs_down'),
           count(distinct e.user_id)
    from public.promo_events e
    where not exists (select 1 from public.internal_accounts i where i.user_id = e.user_id)
    group by e.slot_id;
end;
$function$;
CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.streak_broadcast_audience()
 RETURNS TABLE(user_id uuid, display_name text, brand text, name text, ref text, model_key text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    p.id,
    p.display_name,
    w.brand,
    w.name,
    w.ref,
    case when w.brand is null then null
         else lower(trim(w.brand)) || '|' || lower(trim(w.name)) end
  from profiles p
  left join lateral (
    select w.brand, w.name, w.ref
    from watches w
    where w.user_id = p.id
      and trim(coalesce(w.brand, '')) <> ''
      and trim(coalesce(w.name, ''))  <> ''
    order by w.created_at desc
    limit 1
  ) w on true
  where p.is_suspended = false
    and p.created_at < now() - interval '4 days'
    and coalesce((p.email_prefs->>'updates')::boolean, true) is true
    and not exists (select 1 from logs l where l.user_id = p.id)
    and not exists (select 1 from internal_accounts ia where ia.user_id = p.id)
    -- Already received it as an onboarding email.
    and not exists (
      select 1 from email_campaign_sends s
      where s.user_id = p.id
        and s.campaign_id = '14a9156c-f132-435c-9beb-32800b8c97cb'
    )
    -- Already queued or sent by this broadcast (any status) — makes re-running
    -- the enqueue action idempotent now that it no longer writes campaign sends.
    and not exists (
      select 1 from broadcast_queue q
      where q.uid = p.id and q.label = 'Start your streak — fun fact'
    )
  order by p.created_at desc;
$function$;
CREATE OR REPLACE FUNCTION public.touch_presence()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN RETURN; END IF;
  INSERT INTO public.user_presence (user_id, last_seen_at)
  VALUES (auth.uid(), now())
  ON CONFLICT (user_id) DO UPDATE SET last_seen_at = now();
END;
$function$;
CREATE OR REPLACE FUNCTION public.wear_reminder_targets()
 RETURNS TABLE(user_id uuid, email text, channel text, local_today date)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
  -- `valid` is MATERIALIZED so the timezone-validity filter (pg_timezone_names)
  -- and the cheap predicates run BEFORE any `AT TIME ZONE p.timezone` is evaluated.
  -- Otherwise a single malformed timezone string raises "time zone not recognized"
  -- and aborts the whole set-based run — reminders would go to nobody that hour.
  WITH valid AS MATERIALIZED (
    SELECT p.id, p.timezone
    FROM profiles p
    WHERE p.timezone IS NOT NULL AND p.timezone <> ''
      AND EXISTS (SELECT 1 FROM pg_timezone_names z WHERE z.name = p.timezone)
      AND COALESCE(p.is_suspended, false) = false
      AND COALESCE((p.email_prefs->>'reminders')::boolean, true) = true
      AND p.id NOT IN (SELECT ia.user_id FROM internal_accounts ia)
  ),
  cand AS (
    SELECT v.id AS uid,
           (now() AT TIME ZONE v.timezone)::date AS local_today
    FROM valid v
    WHERE EXTRACT(hour FROM now() AT TIME ZONE v.timezone) = 17
      -- Audience: recently active, OR a new account starting the day after its
      -- first watch was added (the day-1 drip email owns the "add a watch" nudge;
      -- reminders begin once there is something to log). New accounts age out at
      -- 14 days unless they log — then the active branch covers them.
      AND ( EXISTS (SELECT 1 FROM logs l
                    WHERE l.user_id = v.id AND l.created_at >= now() - interval '14 days')
            OR ( EXISTS (SELECT 1 FROM auth.users au
                         WHERE au.id = v.id AND au.created_at >= now() - interval '14 days')
                 AND EXISTS (SELECT 1 FROM watches w
                             WHERE w.user_id = v.id
                               AND (w.created_at AT TIME ZONE v.timezone)::date
                                   < (now() AT TIME ZONE v.timezone)::date) ) )
      -- Skip anyone who has ALREADY engaged for today: a log dated today, OR
      -- any log/post CREATED today in their local timezone. The app lets you
      -- pick a log's date, so posts/wears are often backdated — keying only off
      -- l.date nagged people who'd already posted today (created_at was today
      -- but the assigned date wasn't).
      AND NOT EXISTS (SELECT 1 FROM logs l
                  WHERE l.user_id = v.id
                    AND ( l.date = ((now() AT TIME ZONE v.timezone)::date)::text
                          OR (l.created_at AT TIME ZONE v.timezone)::date = (now() AT TIME ZONE v.timezone)::date ))
      AND NOT EXISTS (SELECT 1 FROM wear_reminder_sends w
                  WHERE w.user_id = v.id
                    AND w.sent_on = (now() AT TIME ZONE v.timezone)::date)
  )
  SELECT c.uid,
         u.email,
         CASE WHEN EXISTS (SELECT 1 FROM device_tokens d
                           WHERE d.user_id = c.uid AND d.platform = 'ios')
              THEN 'push' ELSE 'email' END AS channel,
         c.local_today
  FROM cand c
  JOIN auth.users u ON u.id = c.uid
  WHERE EXISTS (SELECT 1 FROM device_tokens d WHERE d.user_id = c.uid AND d.platform = 'ios')
     OR NOT EXISTS (SELECT 1 FROM wear_reminder_sends w
                    WHERE w.user_id = c.uid AND w.channel = 'email'
                      AND w.sent_on >= c.local_today - 7);
$function$;

